targets.expr:
topk(10,
  histogram_quantile(
    0.95,
    sum by (le, method, uri) (
      rate(http_server_requests_seconds_bucket{application=~"$application", application=~"rtd-admin|user-center-application", namespace=~"$namespace", namespace=~"test", job=~"rtd-admin|user-center-application", method!="OPTIONS"}[5m])
    )
  )
  and on (method, uri)
  sum by (method, uri) (
    rate(http_server_requests_seconds_count{application=~"$application", application=~"rtd-admin|user-center-application", namespace=~"$namespace", namespace=~"test", job=~"rtd-admin|user-center-application", method!="OPTIONS"}[5m])
  ) > 0.0166666667
)

topk(10,
  sum by (method, uri) (
    rate(http_server_requests_seconds_count{application=~"$application", application=~"rtd-admin|user-center-application", namespace=~"$namespace", namespace=~"test", job=~"rtd-admin|user-center-application", method!="OPTIONS"}[5m])
  )
)

sum by (pod) (
  jvm_memory_used_bytes{application=~"$application", application=~"rtd-admin|user-center-application", namespace=~"$namespace", namespace=~"test", job=~"rtd-admin|user-center-application", area="heap"}
)

sum by (pod, id) (
  jvm_memory_used_bytes{application=~"$application", application=~"rtd-admin|user-center-application", namespace=~"$namespace", namespace=~"test", job=~"rtd-admin|user-center-application", area="heap"}
)

sum by (pod) (
  rate(container_cpu_usage_seconds_total{namespace=~"$namespace", namespace=~"test", pod=~"$pod", container!="", container!="POD"}[5m])
)

sum by (pod) (
  container_memory_working_set_bytes{namespace=~"$namespace", namespace=~"test", pod=~"$pod", container!="", container!="POD"}
)

sum by (pod) (
  rate(container_cpu_cfs_throttled_periods_total{namespace=~"$namespace", namespace=~"test", pod=~"$pod", container!="", container!="POD"}[5m])
)
/
clamp_min(
  sum by (pod) (
    rate(container_cpu_cfs_periods_total{namespace=~"$namespace", namespace=~"test", pod=~"$pod", container!="", container!="POD"}[5m])
  ),
  1e-9
)

sum by (pod) (
  jvm_memory_used_bytes{application=~"$application", application=~"rtd-admin|user-center-application", namespace=~"$namespace", namespace=~"test", job=~"rtd-admin|user-center-application", area="heap"}
)

sum by (pod) (
